#!/usr/bin/env sh
#
# VSCodium remote CLI (`codium` inside a remote terminal) for IBM AIX.
# Generated by vsx from the upstream bin/remote-cli script.
#
ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
. "$ROOT/bin/aix-env.sh"

APP_NAME="@APP_NAME@"
VERSION="@VERSION@"
COMMIT="@COMMIT@"
EXEC_NAME="@APP_NAME@"
CLI_SCRIPT="$ROOT/out/server-cli.js"

exec "$ROOT/node" -r "$ROOT/aix-platform-override.js" "$CLI_SCRIPT" "$APP_NAME" "$VERSION" "$COMMIT" "$EXEC_NAME" "$@"
